  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/client\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── Enums ───────────────────────────────────────────────\n\nenum Role {\n  ADMIN\n  STAFF\n  PATIENT\n}\n\nenum ApptStatus {\n  SCHEDULED\n  RESCHEDULED\n  COMPLETED\n  CANCELLED\n  NO_SHOW\n}\n\nenum BookingSource {\n  WEBSITE\n  WALK_IN\n  WHATSAPP_BOT\n}\n\n// ─── Models ──────────────────────────────────────────────\n\nmodel User {\n  id          String   @id @default(uuid())\n  email       String?  @unique\n  phone       String?  @unique // Primary ID for n8n bot\n  password    String?\n  name        String\n  role        Role     @default(PATIENT)\n  patientCode Int?     @unique // Short memorable ID (1000, 1001...)\n  noShowCount Int      @default(0) // Track how many times they didn't show up\n  createdAt   DateTime @default(now())\n\n  // Patient Details\n  dateOfBirth   DateTime?\n  gender        String?\n  address       String?\n  medicalAlerts String? // Critical health info e.g. \"Diabetic, Allergic to Penicillin\"\n\n  // Staff Details\n  // specialized fields removed for single-doctor model\n\n  // Google Calendar integration (Admin only)\n  googleCalendarToken        String?\n  googleCalendarRefreshToken String?\n  googleCalendarConnected    Boolean @default(false)\n\n  // Password reset\n  resetToken       String?\n  resetTokenExpiry DateTime?\n\n  appointments      Appointment[]\n  patientTreatments PatientTreatment[]\n  planChangeLogs    PlanChangeLog[]\n}\n\nmodel Appointment {\n  id        String     @id @default(uuid())\n  startTime DateTime\n  endTime   DateTime\n  status    ApptStatus @default(SCHEDULED)\n  notes     String? // Booking notes from patient/receptionist\n\n  patientId String\n  patient   User   @relation(fields: [patientId], references: [id])\n\n  treatmentId String\n  treatment   Treatment @relation(fields: [treatmentId], references: [id])\n\n  googleEventId String?       @unique\n  bookedBy      BookingSource @default(WEBSITE)\n\n  clinicalNotes ClinicalNote[]\n\n  amountPaid   Int?      @default(0)\n  price        Int       @default(0)\n  discount     Int       @default(0) // Discretionary discount in PKR\n  createdAt    DateTime  @default(now())\n  checkoutTime DateTime?\n\n  // Guest Booking Details\n  guestName  String?\n  guestPhone String?\n  guestEmail String?\n  guestDob   DateTime?\n\n  // Treatment Plan Relation\n  patientTreatmentId String?\n  patientTreatment   PatientTreatment? @relation(fields: [patientTreatmentId], references: [id])\n  sessionNumber      Int?\n  sessionLabel       String?\n  plannedFee         Int? // Expected installment for this session (NOT a billing charge)\n\n  payments Payment[]\n\n  @@index([patientTreatmentId])\n  @@index([startTime])\n}\n\nmodel ClinicalNote {\n  id            String      @id @default(uuid())\n  appointmentId String\n  appointment   Appointment @relation(fields: [appointmentId], references: [id])\n\n  diagnosis      String? // What the doctor found\n  treatmentDone  String // What procedure was performed\n  prescription   String? // Medications prescribed\n  remarks        String? // Follow-up instructions, observations\n  odontogramData Json? // 32-tooth dental chart state\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Treatment {\n  id              String  @id @default(uuid())\n  name            String\n  durationMin     Int\n  price           Int\n  discountedPrice Int?\n  description     String?\n  instructions    String? // For n8n WhatsApp messages\n  isActive        Boolean @default(true)\n  imageUrl        String?\n  category        String  @default(\"General\") // Cosmetic, Restorative, General, Consultations\n  isMultiSession  Boolean @default(false)\n  defaultSessions Int     @default(1)\n\n  appointments      Appointment[]\n  patientTreatments PatientTreatment[]\n}\n\nmodel SystemSettings {\n  id              String @id @default(\"settings\")\n  clinicName      String @default(\"Elite Dental Centre\")\n  workDayStart    String @default(\"09:00\")\n  workDayEnd      String @default(\"17:00\")\n  slotDurationMin Int    @default(30)\n}\n\n// ─── Billing & Treatment Plans ───────────────────────────\n\nenum PaymentMethod {\n  CASH\n  CARD\n  ONLINE\n}\n\nenum TreatmentStatus {\n  ONGOING\n  COMPLETED\n  FULLY_PAID\n}\n\nenum ClinicalStatus {\n  IN_PROGRESS\n  COMPLETED\n  DISCONTINUED\n}\n\nenum FinancialStatus {\n  UNPAID\n  PARTIALLY_PAID\n  FULLY_PAID\n}\n\nmodel PatientTreatment {\n  id          String    @id @default(uuid())\n  patientId   String\n  patient     User      @relation(fields: [patientId], references: [id])\n  treatmentId String\n  treatment   Treatment @relation(fields: [treatmentId], references: [id])\n\n  totalCost     Int // Total agreed price (e.g., 100,000 for braces)\n  totalSessions Int @default(1)\n\n  // Lifecycle enums\n  clinicalStatus  ClinicalStatus  @default(IN_PROGRESS)\n  financialStatus FinancialStatus @default(UNPAID)\n\n  // Legacy status column retained during transition\n  status TreatmentStatus @default(ONGOING)\n\n  startDate DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n\n  appointments Appointment[]\n  payments     Payment[]\n  changeLogs   PlanChangeLog[]\n\n  @@index([patientId])\n  @@index([clinicalStatus])\n}\n\nmodel PlanChangeLog {\n  id                 String           @id @default(uuid())\n  patientTreatmentId String\n  patientTreatment   PatientTreatment @relation(fields: [patientTreatmentId], references: [id], onDelete: Cascade)\n  changedByUserId    String?\n  changedByUser      User?            @relation(fields: [changedByUserId], references: [id])\n  field              String // \"totalCost\" | \"totalSessions\" | \"clinicalStatus\" | \"plannedFee\"\n  oldValue           String\n  newValue           String\n  createdAt          DateTime         @default(now())\n\n  @@index([patientTreatmentId])\n}\n\nmodel Payment {\n  id     String        @id @default(uuid())\n  amount Int\n  method PaymentMethod @default(CASH)\n  date   DateTime      @default(now())\n  notes  String?\n\n  patientTreatmentId String\n  patientTreatment   PatientTreatment @relation(fields: [patientTreatmentId], references: [id])\n\n  appointmentId String?\n  appointment   Appointment? @relation(fields: [appointmentId], references: [id])\n}\n\n// ─── Inventory ───────────────────────────────────────────\n\nmodel Inventory {\n  id           String   @id @default(uuid())\n  itemName     String\n  quantity     Int      @default(0)\n  minThreshold Int      @default(5)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n}\n",
